### Objective
Build a production-ready Issue & Task Tracking application in Flutter using `package:graphql_flutter`. Demonstrate `GraphQLClient` configuration with `HttpLink` and `AuthLink`, declarative query execution with query variables, mutations with automated normalized cache updates, and optimistic UI updates for instant interaction feedback.

```dart
import 'package:flutter/material.dart';
import 'package:graphql_flutter/graphql_flutter.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Initialize Hive storage for persistent GraphQL normalized caching
  await initHiveForFlutter();
  runApp(const GraphQLTaskApp());
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. GRAPHQL CLIENT CONFIGURATION & LINKS
// ─────────────────────────────────────────────────────────────────────────────

class GraphQLConfig {
  static const String _endpoint = 'https://api.mockgraphql.com/graphql';

  static ValueNotifier<GraphQLClient> initializeClient() {
    // 1. HttpLink establishes the POST endpoint transport
    final httpLink = HttpLink(
      _endpoint,
      defaultHeaders: {
        'X-Client-Platform': 'Flutter-Foundation',
      },
    );

    // 2. AuthLink injects JWT credentials dynamically into outbound queries
    final authLink = AuthLink(
      getToken: () async => 'Bearer mock_jwt_access_token_xyz',
    );

    // Combine links: AuthLink -> HttpLink
    final link = authLink.concat(httpLink);

    // 3. Normalized In-Memory Cache with Hive persistence support
    final cache = GraphQLCache(store: HiveStore());

    return ValueNotifier(
      GraphQLClient(
        link: link,
        cache: cache,
        defaultPolicies: DefaultPolicies(
          query: Policies(
            fetchPolicy: FetchPolicy.cacheAndNetwork,
          ),
        ),
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. GRAPHQL OPERATION DOCUMENTS
// ─────────────────────────────────────────────────────────────────────────────

class TaskOperations {
  // Common Fragment to avoid repeating field selections
  static const String taskFieldsFragment = '''
    fragment TaskFields on Task {
      __typename
      id
      title
      isCompleted
      priority
      updatedAt
    }
  ''';

  // Read Query with variables
  static const String fetchTasksQuery = '''
    $taskFieldsFragment
    query FetchTasks(\$limit: Int!) {
      tasks(limit: \$limit) {
        ...TaskFields
      }
    }
  ''';

  // Write Mutation returning the updated entity
  static const String toggleTaskMutation = '''
    $taskFieldsFragment
    mutation ToggleTaskStatus(\$id: ID!, \$isCompleted: Boolean!) {
      toggleTask(id: \$id, isCompleted: \$isCompleted) {
        ...TaskFields
      }
    }
  ''';
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class GraphQLTaskApp extends StatelessWidget {
  const GraphQLTaskApp({super.key});

  @override
  Widget build(BuildContext context) {
    return GraphQLProvider(
      client: GraphQLConfig.initializeClient(),
      child: MaterialApp(
        title: 'GraphQL Architecture',
        debugShowCheckedModeBanner: false,
        theme: ThemeData(
          colorSchemeSeed: Colors.pink,
          useMaterial3: true,
        ),
        home: const TaskDashboardScreen(),
      ),
    );
  }
}

class TaskDashboardScreen extends StatelessWidget {
  const TaskDashboardScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('GraphQL Task Hub'),
        centerTitle: true,
      ),
      body: Query(
        options: QueryOptions(
          document: gql(TaskOperations.fetchTasksQuery),
          variables: const {'limit': 20},
          pollInterval: const Duration(seconds: 45), // Optional background refresh
        ),
        builder: (QueryResult result, {VoidCallback? refetch, FetchMore? fetchMore}) {
          if (result.hasException) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24.0),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Icon(Icons.error_outline_rounded, size: 64, color: Colors.pink),
                    const SizedBox(height: 16),
                    Text(
                      'GraphQL Query Failed',
                      style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold),
                    ),
                    const SizedBox(height: 8),
                    Text(
                      result.exception.toString(),
                      textAlign: TextAlign.center,
                      style: const TextStyle(fontSize: 12, color: Colors.black54),
                    ),
                    const SizedBox(height: 20),
                    FilledButton.icon(
                      onPressed: refetch,
                      icon: const Icon(Icons.refresh),
                      label: const Text('Retry Query'),
                    ),
                  ],
                ),
              ),
            );
          }

          if (result.isLoading && result.data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          final tasksList = (result.data?['tasks'] as List<dynamic>?) ?? [];

          if (tasksList.isEmpty) {
            return const Center(child: Text('No tasks found in graph.'));
          }

          return ListView.separated(
            padding: const EdgeInsets.all(16),
            itemCount: tasksList.length,
            separatorBuilder: (_, __) => const SizedBox(height: 10),
            itemBuilder: (context, index) {
              final task = tasksList[index] as Map<String, dynamic>;
              final String taskId = task['id']?.toString() ?? '';
              final String title = task['title'] as String? ?? 'Untitled';
              final bool isCompleted = task['isCompleted'] as bool? ?? false;
              final String priority = task['priority'] as String? ?? 'NORMAL';

              return Mutation(
                options: MutationOptions(
                  document: gql(TaskOperations.toggleTaskMutation),
                  // Optimistic UI Response: Re-renders UI instantly before server replies!
                  optimisticResult: {
                    'toggleTask': {
                      '__typename': 'Task',
                      'id': taskId,
                      'title': title,
                      'isCompleted': !isCompleted,
                      'priority': priority,
                      'updatedAt': DateTime.now().toIso8601String(),
                    },
                  },
                  onError: (error) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(content: Text('Failed to update task: $error')),
                    );
                  },
                ),
                builder: (RunMutation runMutation, QueryResult? mutationResult) {
                  return Card(
                    elevation: 0.5,
                    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                    child: CheckboxListTile(
                      value: isCompleted,
                      title: Text(
                        title,
                        style: TextStyle(
                          fontWeight: FontWeight.w600,
                          decoration: isCompleted ? TextDecoration.lineThrough : null,
                          color: isCompleted ? Colors.grey : Colors.black87,
                        ),
                      ),
                      subtitle: Text(
                        'Priority: $priority',
                        style: TextStyle(fontSize: 12, color: priority == 'HIGH' ? Colors.redAccent : Colors.grey),
                      ),
                      secondary: CircleAvatar(
                        backgroundColor: isCompleted ? Colors.green.shade50 : Colors.pink.shade50,
                        child: Icon(
                          isCompleted ? Icons.check_circle_outline : Icons.pending_actions,
                          color: isCompleted ? Colors.green : Colors.pink,
                        ),
                      ),
                      onChanged: (bool? newValue) {
                        runMutation({
                          'id': taskId,
                          'isCompleted': newValue ?? false,
                        });
                      },
                    ),
                  );
                },
              );
            },
          );
        },
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **GraphQLClient Architecture & AuthLink**:
   `GraphQLConfig.initializeClient()` constructs an `AuthLink` concatenated to an `HttpLink`. Every query automatically attaches `Authorization: Bearer <token>` without requiring manual header injection in individual repository calls.
2. **Normalized Caching with GraphQLCache**:
   The cache identifies entities by their `__typename` and `id`. Both `TaskFields` fragment and the mutation include `__typename` and `id`, allowing the client to deduplicate entities in memory.
3. **Instant Optimistic UI Mutations**:
   In `MutationOptions`, `optimisticResult` supplies a mock server response with `!isCompleted`. The instant the user taps the checkbox, the local cache is updated and the UI toggles immediately. When the server response returns, it confirms the update without jarring UI jumps.
4. **FetchPolicy.cacheAndNetwork**:
   The client returns cached data instantaneously (cache hit), while simultaneously dispatching a background network request to synchronize fresh data, delivering an instant-load user experience.

